elder.setUsername(username);
}
if (phone != null) {
elder.setPhone(phone);
}
if (address != null) {
elder.setAddress(address);
}
if (emergencyContact != null) {
elder.setEmergencyContact(emergencyContact);
}
if (gender != null) {
elder.setGender(gender);
}
if (age != null) {
elder.setAge(age);
}
