EventService实现了业务逻辑，例如处理异常事件、查询待处理事件、获取事件详情和按老人ID查询事件操作。
public class EventService{
@Autowired
private EventRepository eventRepository;
@Autowired
private NotifyService notifyService;
public boolean handleExceptionEvent(Integer eventId,Integer adminId,String handleMeasures,
boolean contactHospital,String hospitalName,String hospitalPhone){
Event event=eventRepository.findById(eventId)
.orElseThrow(()->new IllegalArgumentException("Event not found with id:"+eventId));
event.setStatus("处理");
event.setHandlerId(adminId);
event.setHandledTime(new Date());
event.setHandleMeasures(handleMeasures);
event.setContactHospital(contactHospital?1:0);
if(contactHospital){
event.setHospitalName(hospitalName);
event.setHospitalPhone(hospitalPhone);
}
Event updatedEvent=eventRepository.save(event);
if(updatedEvent!=null){
notifyService.sendEventHandledNotification(eventId);
}
return updatedEvent!=null;
}}

