技术难点：
对于这个系统我的难点在于无法接入真实物联网设备采集传感器数据，所以设备监测的数据会发生没有依据的问题，对此我用虚拟数据代替真实数据进行系统的运行。
解决方法关键核心代码如下：
@Component
public class SensorDataGeneratorTask{
@Autowired
private DeviceService deviceService;
@Autowired
private SensorDataService sensorDataService;
@Autowired
private EventService eventService;
@Autowired
private NotifyService notifyService;
private final Random random=new Random();
每60秒生成一次虚拟数据
@Scheduled(fixedRate=60000)
public void generateSensorData(){
//获取所有启用状态的设备
List<Device>activeDevices=deviceService.list(
new QueryWrapper<Device>()
.eq("status","在线")
.eq("enable_status","启用")
);
for(Device device:activeDevices){
//每个设备生成10条数据，其中1条异常
generateDataForDevice(device,10,1);
}}
为设备生成传感器数据
private void generateDataForDevice(Device device,int total,int abnormalCount){
int abnormalIndex=random.nextInt(total);//随机选择异常数据位置
for(int i=0;i<total;i++){
boolean isAbnormal=(i==abnormalIndex);
SensorData data=new SensorData();
data.setDeviceId(device.getDeviceId());
data.setElderId(device.getElderId());
data.setDataType(isAbnormal?"静止":randomType());//异常为静止
data.setDuration(isAbnormal?25:random.nextInt(30)+1);//异常25分钟
data.setPosition(randomPosition());
data.setIsTrigger(isAbnormal?1:0);//异常触发告警
data.setReportTime(new Date());
sensorDataService.save(data);
异常数据创建事件并通知
if(isAbnormal){
createEvent(device,data);
}}
创建异常事件
private void createEvent(Device device,SensorData data){
Event event=new Event();
event.setType("异常监测");
event.setLevel("中危");
event.setLocation(data.getPosition());
event.setTriggerTime(new Date());
event.setStatus("待处理");
event.setElderId(device.getElderId());
eventService.save(event);
notifyService.sendNotificationByLevel(event);//发送通知
}
随机生成数据类型
private String randomType(){
